content:
{
  "test_cases": [
    {
      "id": "TC-01",
      "title": "OBU initiates termination upon trackside order",
      "covers": [
        "ETC-012"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "An active communication session is established between the OBU and the trackside (RBC).",
      "test_inputs": "Trackside sends a 'Termination of Communication Session' order.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "The trackside sends a termination order to the OBU.",
          "expected": "The OBU initiates the termination of the communication session."
        }
      ]
    },
    {
      "id": "TC-02",
      "title": "OBU does not initiate termination without trackside order or condition",
      "covers": [
        "ETC-012"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "An active communication session is established. No termination conditions from SUBSET-026 are fulfilled.",
      "test_inputs": "No trackside order is sent. No termination condition is triggered.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Wait for a duration longer than the fixed waiting time without any trackside order or termination condition.",
          "expected": "The OBU does not initiate the termination of the communication session."
        }
      ]
    },
    {
      "id": "TC-03",
      "title": "OBU repeats termination message if no acknowledgement is received",
      "covers": [
        "ETC-013"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The OBU has initiated the termination of the communication session and sent the 'Termination of Communication Session' message.",
      "test_inputs": "No acknowledgement is received from the trackside within the fixed waiting time.",
      "assumptions": "The fixed waiting time is defined in SUBSET-026 Appendix A.3.1.",
      "steps": [
        {
          "no": 1,
          "action": "The OBU sends the 'Termination of Communication Session' message.",
          "expected": "The OBU waits for the fixed waiting time."
        },
        {
          "no": 2,
          "action": "The fixed waiting time expires without an acknowledgement.",
          "expected": "The OBU repeats the 'Termination of Communication Session' message."
        }
      ]
    },
    {
      "id": "TC-04",
      "title": "OBU considers session terminated after maximum repetitions without acknowledgement",
      "covers": [
        "ETC-014"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The OBU is in the process of terminating the communication session and has been repeating the termination message.",
      "test_inputs": "No acknowledgement is received after the last repetition of the termination message.",
      "assumptions": "The defined number of repetitions is as per SUBSET-026 Appendix A.3.1.",
      "steps": [
        {
          "no": 1,
          "action": "The OBU sends the 'Termination of Communication Session' message for the defined number of times.",
          "expected": "The OBU waits for the fixed waiting time after the last sending."
        },
        {
          "no": 2,
          "action": "The fixed waiting time expires after the last sending without an acknowledgement.",
          "expected": "The OBU considers the communication session terminated."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-045-01",
      "title": "Driver requests display of estimated front end position",
      "covers": [
        "ETC-045"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The OBU is powered on and in a state where the driver can interact with the HMI. The train is moving or stationary with a valid position estimate.",
      "test_inputs": "Driver command: 'Show Position'",
      "assumptions": "The HMI has a specific button or menu item to request the position display.",
      "steps": [
        {
          "no": 1,
          "action": "Verify that the geographical position of the train's estimated front end is not displayed on the HMI before the request.",
          "expected": "The position display is hidden or inactive."
        },
        {
          "no": 2,
          "action": "The driver issues the request to display the geographical position.",
          "expected": "The OBU displays the geographical position in relation to the track kilometre of the train's estimated front end."
        }
      ]
    },
    {
      "id": "TC-045-02",
      "title": "Driver requests to stop display of estimated front end position",
      "covers": [
        "ETC-045"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The geographical position of the train's estimated front end is currently displayed on the HMI.",
      "test_inputs": "Driver command: 'Hide Position'",
      "assumptions": "The HMI has a specific button or menu item to stop the position display.",
      "steps": [
        {
          "no": 1,
          "action": "Verify that the geographical position is currently visible on the HMI.",
          "expected": "The position display is active and showing the track kilometre value."
        },
        {
          "no": 2,
          "action": "The driver issues the request to stop the display.",
          "expected": "The OBU stops displaying the geographical position of the train's estimated front end."
        }
      ]
    },
    {
      "id": "TC-046-01",
      "title": "Position calculation includes distance travelled since reference",
      "covers": [
        "ETC-046"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The OBU has a known geographical reference location (e.g., a balise or GPS fix) at track kilometre K_ref. The train travels a known distance D from this reference.",
      "test_inputs": "Reference location: K_ref = 10.0 km. Distance travelled: D = 500 m.",
      "assumptions": "The OBU's internal odometry or speed integration is accurate enough to measure D=500m for this test. The track is straight and no curve corrections are needed for this simple check.",
      "steps": [
        {
          "no": 1,
          "action": "Set the OBU's geographical reference location to track kilometre 10.0 km.",
          "expected": "The OBU records the reference location as 10.0 km."
        },
        {
          "no": 2,
          "action": "Move the train (or simulate movement) for a distance of 500 meters from the reference location.",
          "expected": "The OBU calculates the distance travelled as 500 meters."
        },
        {
          "no": 3,
          "action": "Request the display of the geographical position of the train's estimated front end.",
          "expected": "The displayed position is 10.5 km (10.0 km + 0.5 km), confirming that the distance travelled since the reference was added."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-050-01",
      "title": "MA uzunluğunu tam kapsamayan SSP/gradient ile MA kabul edilmemesi",
      "covers": [
        "ETC-050"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "OBU, SSP ve gradient verilerini içeren bir MA alacak konumdadır.",
      "test_inputs": "MA uzunluğu 1000 m olan, ancak SSP/gradient verileri yalnızca 800 m'lik kısmı kapsayan bir MA paketi.",
      "assumptions": "MA uzunluğu ve SSP/gradient kapsamı, SUBSET-026 §3.7.2.3.1–3.7.2.3.2 tanımına göre hesaplanmaktadır.",
      "steps": [
        {
          "no": 1,
          "action": "SSP ve gradient verileri MA'nın tam uzunluğunu kapsamayan bir MA paketi OBU'ya iletilir.",
          "expected": "OBU, MA'yı ve ilişkili mod profillerini kabul etmez."
        },
        {
          "no": 2,
          "action": "OBU'nun MA kabul durumu kontrol edilir.",
          "expected": "MA aktif hale gelmez ve ilgili mod profili yüklenmez."
        }
      ]
    },
    {
      "id": "TC-050-02",
      "title": "MA uzunluğunu tam kapsayan SSP/gradient ile MA kabul edilmesi",
      "covers": [
        "ETC-050"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU, SSP ve gradient verilerini içeren bir MA alacak konumdadır.",
      "test_inputs": "MA uzunluğu 1000 m olan ve SSP/gradient verileri 1000 m'lik tam uzunluğu kapsayan bir MA paketi.",
      "assumptions": "MA uzunluğu ve SSP/gradient kapsamı, SUBSET-026 §3.7.2.3.1–3.7.2.3.2 tanımına göre hesaplanmaktadır.",
      "steps": [
        {
          "no": 1,
          "action": "SSP ve gradient verileri MA'nın tam uzunluğunu kapsayan bir MA paketi OBU'ya iletilir.",
          "expected": "OBU, MA'yı ve ilişkili mod profillerini kabul eder."
        },
        {
          "no": 2,
          "action": "OBU'nun MA kabul durumu kontrol edilir.",
          "expected": "MA aktif hale gelir ve ilgili mod profili yüklenir."
        }
      ]
    },
    {
      "id": "TC-050-03",
      "title": "SSP/gradient kapsamı MA uzunluğundan 1 m kısa olan sınır durumu",
      "covers": [
        "ETC-050"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "OBU, SSP ve gradient verilerini içeren bir MA alacak konumdadır.",
      "test_inputs": "MA uzunluğu 1000 m olan, ancak SSP/gradient verileri 999 m'lik kısmı kapsayan bir MA paketi.",
      "assumptions": "MA uzunluğu ve SSP/gradient kapsamı, SUBSET-026 §3.7.2.3.1–3.7.2.3.2 tanımına göre hesaplanmaktadır.",
      "steps": [
        {
          "no": 1,
          "action": "SSP ve gradient verileri MA'nın tam uzunluğunu 1 m eksik kapsayan bir MA paketi OBU'ya iletilir.",
          "expected": "OBU, MA'yı ve ilişkili mod profillerini kabul etmez."
        },
        {
          "no": 2,
          "action": "OBU'nun MA kabul durumu kontrol edilir.",
          "expected": "MA aktif hale gelmez ve ilgili mod profili yüklenmez."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-01",
      "title": "Safe radio connection loss triggers immediate reconnection attempt",
      "covers": [
        "ETC-010"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in operational mode. A safe radio connection is established with a specific radio system (e.g., GSM-R). EURORADIO is active.",
      "test_inputs": "Simulated loss of safe radio connection signal from EURORADIO.",
      "assumptions": "The radio system previously used for the successful connection is available and reachable.",
      "steps": [
        {
          "no": 1,
          "action": "Establish a safe radio connection with the radio system.",
          "expected": "OBU status indicates an active safe radio connection."
        },
        {
          "no": 2,
          "action": "Simulate the loss of the safe radio connection via EURORADIO.",
          "expected": "OBU immediately initiates an attempt to set up a new safe radio connection with the same radio system."
        }
      ]
    },
    {
      "id": "TC-02",
      "title": "Repeated reconnection attempts until success",
      "covers": [
        "ETC-011"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in operational mode. A communication session is established. The safe radio connection is lost.",
      "test_inputs": "Simulated radio interference preventing connection for a short duration, followed by restoration of radio availability.",
      "assumptions": "The session is not terminated and the train has not passed the RIU termination location.",
      "steps": [
        {
          "no": 1,
          "action": "Cause the loss of the safe radio connection during an active session.",
          "expected": "OBU starts repeating attempts to set up a new safe radio connection."
        },
        {
          "no": 2,
          "action": "Keep the radio system unavailable for a defined period (e.g., 30 seconds) to force multiple failed attempts.",
          "expected": "OBU continues to repeat the connection attempts without stopping."
        },
        {
          "no": 3,
          "action": "Restore radio system availability.",
          "expected": "OBU successfully establishes a new safe radio connection and stops repeating the attempts."
        }
      ]
    },
    {
      "id": "TC-03",
      "title": "Reconnection attempts stop when session is terminated",
      "covers": [
        "ETC-011"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "OBU is in operational mode. A communication session is established. The safe radio connection is lost.",
      "test_inputs": "Command to terminate the communication session.",
      "assumptions": "The radio system remains unavailable to ensure the stop condition is due to session termination, not connection success.",
      "steps": [
        {
          "no": 1,
          "action": "Cause the loss of the safe radio connection during an active session.",
          "expected": "OBU starts repeating attempts to set up a new safe radio connection."
        },
        {
          "no": 2,
          "action": "Issue a command to terminate the communication session.",
          "expected": "OBU stops repeating the attempts to set up a new safe radio connection."
        }
      ]
    },
    {
      "id": "TC-04",
      "title": "Reconnection attempts stop when train passes RIU termination location",
      "covers": [
        "ETC-011"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "OBU is in operational mode. A communication session is established with an RIU order specifying a termination location. The safe radio connection is lost.",
      "test_inputs": "Train movement data simulating passage of the RIU termination location.",
      "assumptions": "The radio system remains unavailable to ensure the stop condition is due to passing the location, not connection success.",
      "steps": [
        {
          "no": 1,
          "action": "Cause the loss of the safe radio connection during an active session.",
          "expected": "OBU starts repeating attempts to set up a new safe radio connection."
        },
        {
          "no": 2,
          "action": "Simulate the train passing the location specified in the RIU order to terminate the communication session.",
          "expected": "OBU stops repeating the attempts to set up a new safe radio connection."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-ETC-026-01",
      "title": "Report position to RBC referring to last passed compliant LRBG",
      "covers": [
        "ETC-026"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in operational mode. A compliant LRBG (LRBG-1) has been passed. The OBU has reported its position to the RBC.",
      "test_inputs": "Train moves forward. A new compliant LRBG (LRBG-2) is passed.",
      "assumptions": "LRBG-1 and LRBG-2 meet the conditions of SUBSET-026 §3.6.5.1.8. Linking consistency is not checked or LRBGs are not marked as unlinked.",
      "steps": [
        {
          "no": 1,
          "action": "Pass LRBG-1 and allow the OBU to report position to the RBC.",
          "expected": "The OBU reports the train position to the RBC referring to LRBG-1."
        },
        {
          "no": 2,
          "action": "Pass LRBG-2 and allow the OBU to report position to the RBC.",
          "expected": "The OBU reports the train position to the RBC referring to LRBG-2 (the last passed compliant LRBG)."
        }
      ]
    },
    {
      "id": "TC-ETC-026-02",
      "title": "Accept trackside information referring to recently reported LRBG",
      "covers": [
        "ETC-026"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU has reported position to RBC referring to LRBG-1. LRBG-1 is within the minimum number of recently reported LRBGs defined in SUBSET-026 §3.6.2.2.2 c).",
      "test_inputs": "RBC sends trackside information (e.g., movement authority) referring to LRBG-1.",
      "assumptions": "The minimum number of recently reported LRBGs is at least 1.",
      "steps": [
        {
          "no": 1,
          "action": "Receive trackside information from RBC that refers to LRBG-1.",
          "expected": "The OBU accepts the trackside information."
        }
      ]
    },
    {
      "id": "TC-ETC-026-03",
      "title": "Reject trackside information referring to LRBG outside recent window",
      "covers": [
        "ETC-026"
      ],
      "type": "Hata",
      "priority": "Orta",
      "preconditions": "OBU has reported position to RBC referring to LRBG-2. LRBG-1 is no longer within the minimum number of recently reported LRBGs (e.g., it has been pushed out of the window by newer LRBGs).",
      "test_inputs": "RBC sends trackside information referring to LRBG-1.",
      "assumptions": "The minimum number of recently reported LRBGs is 1, so only LRBG-2 is considered 'recent'.",
      "steps": [
        {
          "no": 1,
          "action": "Receive trackside information from RBC that refers to LRBG-1.",
          "expected": "The OBU does not accept the trackside information (or rejects it as invalid/out-of-window)."
        }
      ]
    },
    {
      "id": "TC-ETC-026-04",
      "title": "Compliance check with linking consistency enabled",
      "covers": [
        "ETC-026"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "Linking consistency check is enabled. LRBG-1 is linked and announced in linking. LRBG-2 is not linked or not announced in linking.",
      "test_inputs": "Train passes LRBG-1, then LRBG-2.",
      "assumptions": "LRBG-1 meets all other conditions of SUBSET-026 §3.6.5.1.8. LRBG-2 fails the linking consistency condition.",
      "steps": [
        {
          "no": 1,
          "action": "Pass LRBG-1 and allow OBU to report position.",
          "expected": "OBU reports position referring to LRBG-1 (compliant)."
        },
        {
          "no": 2,
          "action": "Pass LRBG-2 and allow OBU to report position.",
          "expected": "OBU continues to report position referring to LRBG-1, as LRBG-2 is not compliant due to linking consistency check."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-055-01",
      "title": "MA request includes all applicable reasons",
      "covers": [
        "ETC-055"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in Level 2 and connected to RBC. Multiple MA request conditions are active simultaneously (e.g., Section timer expired and track description deletion).",
      "test_inputs": "Simulate conditions that trigger multiple MA request reasons defined in SUBSET-026 §3.8.2.1.1.",
      "assumptions": "The RBC or a test tool can capture and decode the MA request message to verify the content of the 'MA request reasons' field.",
      "steps": [
        {
          "no": 1,
          "action": "Trigger a condition that generates a specific MA request reason (e.g., Section timer expiry).",
          "expected": "OBU prepares an MA request."
        },
        {
          "no": 2,
          "action": "Trigger a second condition that generates a different MA request reason (e.g., track description deletion) before the request is sent.",
          "expected": "OBU updates the pending MA request to include the new reason."
        },
        {
          "no": 3,
          "action": "Allow the OBU to send the MA request to the RBC.",
          "expected": "The sent MA request message contains both the first and the second MA request reason in the appropriate field."
        }
      ]
    },
    {
      "id": "TC-056-01",
      "title": "MA request triggered by perturbation-location criterion",
      "covers": [
        "ETC-056"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in Level 2. A valid MA is active. The perturbation-location criterion is defined in the current MA.",
      "test_inputs": "Train speed and position data to simulate the train front passing the calculated perturbation location.",
      "assumptions": "The perturbation location is calculated based on the current MA parameters and is known to the test setup.",
      "steps": [
        {
          "no": 1,
          "action": "Move the train front to a position just before the perturbation location.",
          "expected": "No MA request is sent to the RBC."
        },
        {
          "no": 2,
          "action": "Move the train front to pass the perturbation location.",
          "expected": "The OBU triggers and sends an MA request to the RBC."
        }
      ]
    },
    {
      "id": "TC-056-02",
      "title": "MA request triggered by Section timer/LOA speed timer criterion",
      "covers": [
        "ETC-056"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in Level 2. A valid MA is active. The Section timer or LOA speed timer is running.",
      "test_inputs": "Time progression to simulate the timer reaching its limit.",
      "assumptions": "The timer value is set to a short duration for testing purposes to avoid long wait times.",
      "steps": [
        {
          "no": 1,
          "action": "Wait until the Section timer or LOA speed timer reaches its defined limit.",
          "expected": "The OBU triggers and sends an MA request to the RBC."
        }
      ]
    },
    {
      "id": "TC-057-01",
      "title": "MA request triggered by track description deletion (valid situation)",
      "covers": [
        "ETC-057"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in Level 2. A valid MA is active. The track description contains elements that can be deleted.",
      "test_inputs": "RBC message deleting a part of the track description under a situation defined in SUBSET-026 Appendix A.3.4 (excluding a, b, f, k).",
      "assumptions": "The specific situation chosen for the test is one of the valid situations listed in SUBSET-026 Appendix A.3.4 (e.g., situation c).",
      "steps": [
        {
          "no": 1,
          "action": "Send a message from the RBC that deletes a part of the track description under a valid situation (e.g., situation c).",
          "expected": "The OBU processes the deletion and triggers an MA request to the RBC."
        }
      ]
    },
    {
      "id": "TC-057-02",
      "title": "No MA request triggered by track description deletion (excluded situation)",
      "covers": [
        "ETC-057"
      ],
      "type": "Hata",
      "priority": "Orta",
      "preconditions": "OBU is in Level 2. A valid MA is active. The track description contains elements that can be deleted.",
      "test_inputs": "RBC message deleting a part of the track description under an excluded situation (e.g., situation a).",
      "assumptions": "The specific situation chosen for the test is one of the excluded situations listed in SUBSET-026 Appendix A.3.4 (situation a).",
      "steps": [
        {
          "no": 1,
          "action": "Send a message from the RBC that deletes a part of the track description under an excluded situation (situation a).",
          "expected": "The OBU processes the deletion but does NOT trigger an MA request to the RBC."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-ETC-075-01",
      "title": "OBU'nun desteklemediği infill ortamı talebinin yok sayılması",
      "covers": [
        "ETC-075"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU, desteklenen infill ortamları listesine göre yapılandırılmıştır. OBU, geçerli bir balis grubundan önceki seyrine ait güncel bilgiyi almıştır.",
      "test_inputs": "Desteklenmeyen infill ortamı talep eden bir announcement balis grubu simülasyonu.",
      "assumptions": "OBU'nun desteklemediği bir infill ortamı (örneğin, OBU'da donanımı olmayan bir frekans bandı veya protokol) tanımlanmıştır.",
      "steps": [
        {
          "no": 1,
          "action": "OBU'ya desteklenmeyen bir infill ortamı talep eden bir announcement balis grubu sinyali verilir.",
          "expected": "OBU, bu talebi yok sayar ve infill bağlantısı kurmaya çalışmaz."
        },
        {
          "no": 2,
          "action": "OBU'nun çalışma durumu ve kullandığı bilgi kaynağı gözlemlenir.",
          "expected": "OBU, önceki balis grubundan aldığı bilgilere göre çalışmaya devam eder."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-015-01",
      "title": "Güç açıldığında GSM-R kayıt emrinin verilmesi",
      "covers": [
        "ETC-015"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU kapalı durumdadır. GSM-R Mobil Terminal bağlıdır ve kayıt için hazırdır.",
      "test_inputs": "",
      "assumptions": "GSM-R Mobil Terminal'in kayıt durumunu gözlemlemek için bir izleme aracı veya log erişimi mevcuttur.",
      "steps": [
        {
          "no": 1,
          "action": "OBU'ya güç verilir.",
          "expected": "OBU, bağlı GSM-R Mobil Terminal'in GSM-R Radyo Ağı'na kaydolması için emir verir."
        }
      ]
    },
    {
      "id": "TC-015-02",
      "title": "Sürücünün yeni GSM-R Radyo Ağı kimliği girmesi üzerine kayıt emri",
      "covers": [
        "ETC-015"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU çalışır durumdadır. Sürücü arayüzü erişilebilir.",
      "test_inputs": "Yeni GSM-R Radyo Ağı kimliği (örn: 901).",
      "assumptions": "",
      "steps": [
        {
