      "title": "OBU reads next main signal balise group and ignores subsequent infill",
      "covers": [
        "ETC-076"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in operational mode and has not yet read the next main signal balise group.",
      "test_inputs": "Infill data from loop, Main signal balise group data.",
      "assumptions": "The OBU is configured to process infill data from loops before reading the next main signal balise group.",
      "steps": [
        {
          "no": 1,
          "action": "Transmit infill information from the loop to the OBU.",
          "expected": "OBU processes and stores the infill information."
        },
        {
          "no": 2,
          "action": "Transmit the next main signal balise group data to the OBU.",
          "expected": "OBU reads and processes the main signal balise group."
        },
        {
          "no": 3,
          "action": "Transmit additional infill information from the loop to the OBU.",
          "expected": "OBU ignores the additional infill information and does not update its state based on it."
        }
      ]
    },
    {
      "id": "TC-076-02",
      "title": "OBU detects missed main signal balise group and ignores subsequent infill",
      "covers": [
        "ETC-076"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "OBU is in operational mode and has not yet read the next main signal balise group.",
      "test_inputs": "Infill data from loop, Simulation of missed main signal balise group.",
      "assumptions": "The OBU has a mechanism to detect that the main signal balise group was missed (e.g., timeout or position-based detection).",
      "steps": [
        {
          "no": 1,
          "action": "Transmit infill information from the loop to the OBU.",
          "expected": "OBU processes and stores the infill information."
        },
        {
          "no": 2,
          "action": "Simulate the condition where the next main signal balise group is missed (e.g., by not transmitting it and allowing the detection timeout to expire).",
          "expected": "OBU detects that the main signal balise group was missed."
        },
        {
          "no": 3,
          "action": "Transmit additional infill information from the loop to the OBU.",
          "expected": "OBU ignores the additional infill information and does not update its state based on it."
        }
      ]
    }
  ]
}

