          "action": "Check the failed authentication count of the account.",
          "expected": "The failed authentication count remains 2 and is not reset to 0."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "SMS code generation does not reset failed count at lockout threshold boundary",
      "covers": [
        "KDH-024"
      ],
      "type": "Sınır",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with a failed authentication count equal to the maximum allowed before lockout (e.g., 4 out of 5).",
      "test_inputs": "Valid company representative credentials, valid phone number for SMS.",
      "assumptions": "The lockout threshold is 5 failed attempts as per NIST SP 800-63B-4 §3.1.3.2.",
      "steps": [
        {
          "no": 1,
          "action": "Perform 4 failed login attempts with the company representative account.",
          "expected": "The failed authentication count is 4."
        },
        {
          "no": 2,
          "action": "Request a new SMS one-time code for the company representative.",
          "expected": "A new SMS code is generated and sent."
        },
        {
          "no": 3,
          "action": "Check the failed authentication count of the account.",
          "expected": "The failed authentication count remains 4 and is not reset."
        },
        {
          "no": 4,
          "action": "Perform one more failed login attempt.",
          "expected": "The account is locked due to reaching the 5th failed attempt."
        }
      ]
    },
    {
      "id": "TC-003",
      "title": "SMS code generation does not reset failed count when account is already locked",
      "covers": [
        "KDH-024"
      ],
      "type": "Hata",
      "priority": "Orta",
      "preconditions": "A company representative account is locked due to exceeding the maximum failed authentication attempts.",
      "test_inputs": "Valid company representative credentials, valid phone number for SMS.",
      "assumptions": "The system may or may not allow SMS code generation for locked accounts; this test verifies that if allowed, the count is not reset.",
      "steps": [
        {
          "no": 1,
          "action": "Verify the account is in a locked state with a failed authentication count of 5 or more.",
          "expected": "The account status is 'Locked' and the failed count is >= 5."
        },
        {
          "no": 2,
          "action": "Attempt to request a new SMS one-time code for the locked company representative account.",
          "expected": "If the system allows the request, a new SMS code is generated. If not, an error is returned."
        },
        {
          "no": 3,
          "action": "Check the failed authentication count of the account after the SMS request attempt.",
          "expected": "The failed authentication count is not reset to 0. It remains at the locked value or is incremented if the request itself is considered a failed action, but it is not cleared."
        }
      ]
    }
  ]
}

