{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Multiple authenticator failure threshold triggers disablement",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with password and second-factor (e.g., TOTP) enabled. The account is not currently disabled. The failure threshold defined in VBP SDD §14 is known (assumed to be 5 for this test).",
      "test_inputs": "Valid username, invalid password, invalid second-factor code.",
      "assumptions": "The failure threshold for consecutive failed attempts is 5. The system tracks failures per authenticator type and per account.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login with valid username, invalid password, and valid second-factor code.",
          "expected": "Authentication fails. Password failure count increments to 1."
        },
        {
          "no": 2,
          "action": "Attempt login with valid username, valid password, and invalid second-factor code.",
          "expected": "Authentication fails. Second-factor failure count increments to 1."
        },
        {
          "no": 3,
          "action": "Repeat the sequence of invalid password and invalid second-factor attempts until the total consecutive failed attempts reach the threshold (5 attempts total, involving both authenticators).",
          "expected": "The 5th failed attempt is recorded. The system detects that the threshold has been reached and that more than one authenticator was involved in the consecutive failures."
        },
        {
          "no": 4,
          "action": "Check the status of the password authenticator for the account.",
          "expected": "The password authenticator is disabled."
        },
        {
          "no": 5,
          "action": "Check the status of the second-factor authenticator for the account.",
          "expected": "The second-factor authenticator is disabled."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Single authenticator failure does not disable other authenticators",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "A company representative account exists with password and second-factor enabled. The account is not currently disabled. The failure threshold is 5.",
      "test_inputs": "Valid username, invalid password, valid second-factor code.",
      "assumptions": "The failure threshold is 5. The requirement specifies disabling only if *more than one* authenticator is involved in the consecutive failures.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login 5 times with valid username, invalid password, and valid second-factor code.",
          "expected": "All 5 attempts fail. Only the password authenticator is involved in the failures."
        },
        {
          "no": 2,
          "action": "Check the status of the password authenticator.",
          "expected": "The password authenticator is disabled (due to reaching threshold for that specific authenticator, per standard lockout policies, though KDH-038 specifically addresses the multi-authenticator case. However, to strictly test KDH-038's condition 'if more than one... is involved', we verify that the *other* authenticator is NOT disabled by this specific rule)."
        },
        {
          "no": 3,
          "action": "Check the status of the second-factor authenticator.",
          "expected": "The second-factor authenticator remains enabled, as it was not involved in the failed attempts."
        }
      ]
    },
    {
      "id": "TC-003",
      "title": "Threshold not reached with multiple authenticators",
      "covers": [
        "KDH-038"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "A company representative account exists with password and second-factor enabled. The failure threshold is 5.",
      "test_inputs": "Valid username, invalid password, invalid second-factor code.",
      "assumptions": "The failure threshold is 5.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login 4 times with valid username, invalid password, and invalid second-factor code.",
          "expected": "All 4 attempts fail. Both authenticators are involved, but the threshold (5) is not reached."
        },
        {
          "no": 2,
          "action": "Check the status of the password authenticator.",
          "expected": "The password authenticator remains enabled."
        },
        {
          "no": 3,
          "action": "Check the status of the second-factor authenticator.",
          "expected": "The second-factor authenticator remains enabled."
        }
      ]
    }
  ]
}

